package com.amdocs.telecom.service;import com.amdocs.telecom.util.DBConnection;import java.sql.*;import java.util.*;import java.time.*;
public class TicketService{private final SLAService sla=new SLAService(); public long create(String customer,String service,String category,String desc,String priority,String severity,String actor)throws SQLException{try(Connection c=DBConnection.getInstance().get()){int mins;try(PreparedStatement p=c.prepareStatement("SELECT resolution_minutes FROM sla_configuration WHERE priority=?")){p.setString(1,priority);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Invalid priority");mins=r.getInt(1);}}Timestamp now=Timestamp.from(Instant.now()),deadline=sla.deadline(now,mins);String num="TT-"+Year.now().getValue()+"-"+String.format("%06d",Math.abs(new Random().nextInt(999999)));try(PreparedStatement p=c.prepareStatement("INSERT INTO trouble_tickets(ticket_number,customer_id,service_id,category,description,priority,severity,created_date,status,sla_deadline) VALUES(?,?,?,?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,num);p.setString(2,customer);p.setString(3,service);p.setString(4,category);p.setString(5,desc);p.setString(6,priority);p.setString(7,severity);p.setTimestamp(8,now);p.setString(9,"OPEN");p.setTimestamp(10,deadline);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();long id=r.getLong(1);history(c,id,null,"OPEN",actor,"Ticket created");notify(c,customer,"Ticket created: "+num,"TICKET_CREATION");return id;}}}}
 public List<Map<String,Object>> list(String customer,String engineer)throws SQLException{String sql="SELECT t.*,s.service_name FROM trouble_tickets t JOIN telecom_services s ON s.service_id=t.service_id WHERE (? IS NULL OR t.customer_id=?) AND (? IS NULL OR t.assigned_engineer_id=?) ORDER BY CASE priority WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 ELSE 4 END,created_date";List<Map<String,Object>>a=new ArrayList<>();try(Connection c=DBConnection.getInstance().get();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,customer);p.setString(2,customer);p.setString(3,engineer);p.setString(4,engineer);try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object>m=new LinkedHashMap<>();m.put("id",r.getLong("ticket_id"));m.put("ticketNumber",r.getString("ticket_number"));m.put("service",r.getString("service_name"));m.put("category",r.getString("category"));m.put("priority",r.getString("priority"));m.put("status",r.getString("status"));m.put("engineer",r.getString("assigned_engineer_id"));m.put("slaDeadline",r.getTimestamp("sla_deadline"));m.put("slaStatus",sla.status(r.getTimestamp("sla_deadline")));m.put("remainingMinutes",sla.remainingMinutes(r.getTimestamp("sla_deadline")));m.put("resolution",r.getString("resolution"));a.add(m);}}}return a;}
 public void status(long id,String status,String actor,String remarks)throws SQLException{try(Connection c=DBConnection.getInstance().get()){String old;try(PreparedStatement p=c.prepareStatement("SELECT status FROM trouble_tickets WHERE ticket_id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Ticket not found");old=r.getString(1);}}try(PreparedStatement p=c.prepareStatement("UPDATE trouble_tickets SET status=?,updated_at=CURRENT_TIMESTAMP WHERE ticket_id=?")){p.setString(1,status);p.setLong(2,id);p.executeUpdate();}history(c,id,old,status,actor,remarks);}}
 public void resolve(long id,String root,String resolution,String code,String actor)throws SQLException{try(Connection c=DBConnection.getInstance().get();PreparedStatement p=c.prepareStatement("UPDATE trouble_tickets SET root_cause=?,resolution=?,resolution_code=?,resolution_date=CURRENT_TIMESTAMP,status='RESOLVED',updated_at=CURRENT_TIMESTAMP WHERE ticket_id=?")){p.setString(1,root);p.setString(2,resolution);p.setString(3,code);p.setLong(4,id);p.executeUpdate();history(c,id,"IN_PROGRESS","RESOLVED",actor,"Resolved: "+code);notify(c,actor,"Ticket resolved: "+id,"TICKET_RESOLUTION");}}
 public List<Map<String,Object>> history(long id)throws SQLException{return rows("SELECT old_status,new_status,changed_by,changed_date,remarks FROM ticket_status_history WHERE ticket_id="+id+" ORDER BY changed_date");}private List<Map<String,Object>>rows(String s)throws SQLException{List<Map<String,Object>>a=new ArrayList<>();try(Connection c=DBConnection.getInstance().get();Statement p=c.createStatement();ResultSet r=p.executeQuery(s)){ResultSetMetaData md=r.getMetaData();while(r.next()){Map<String,Object>m=new LinkedHashMap<>();for(int i=1;i<=md.getColumnCount();i++)m.put(md.getColumnLabel(i),r.getObject(i));a.add(m);}}return a;}private void history(Connection c,long id,String old,String ne,String actor,String rem)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO ticket_status_history(ticket_id,old_status,new_status,changed_by,remarks) VALUES(?,?,?,?,?)")){p.setLong(1,id);p.setString(2,old);p.setString(3,ne);p.setString(4,actor);p.setString(5,rem);p.executeUpdate();}}private void notify(Connection c,String to,String msg,String type)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO notifications(recipient_id,message,notification_type) VALUES(?,?,?)")){p.setString(1,to);p.setString(2,msg);p.setString(3,type);p.executeUpdate();}}
}
